export const BRIGHTLOCAL_TEMPLATES: readonly RegistryTemplate[] = [
  {
    "id": "citations-hub",
    "label": "Citations Hub",
    "description": "Citations vertical hub: score summary, sync status, directory table, Build Citations CTA.",
    "source": "// Citations Hub — Citations vertical hub: score summary, sync status, directory table, Build Citations CTA.\n//\n// First vertical hub template (the \"lazy prompt\" answer for \"start with\n// the hub page for Citations\"). Same shell mount as page-skeleton.jsx —\n// SidebarProvider > GlobalLayout > GlobalLayoutSidebar > Sidebar compound\n// family — with the Citations nav item active and citations-specific\n// content per rules/05-product-map.md. Edit freely; re-run\n// `node scripts/generate-registry-templates.mjs`.\n\nimport {\n  Avatar,\n  AvatarFallback,\n  Badge,\n  Button,\n  Card,\n  CardContent,\n  GlobalLayout,\n  GlobalLayoutContent,\n  GlobalLayoutContentBody,\n  GlobalLayoutContentHeader,\n  GlobalLayoutSidebar,\n  Logo,\n  Separator,\n  Sidebar,\n  SidebarAccountDropdown,\n  SidebarContent,\n  SidebarFooter,\n  SidebarGroup,\n  SidebarGroupContent,\n  SidebarHeader,\n  SidebarMenu,\n  SidebarMenuButton,\n  SidebarMenuItem,\n  SidebarProvider,\n  SidebarTrigger,\n  Table,\n  TableBody,\n  TableCell,\n  TableHead,\n  TableHeader,\n  TableRow,\n  TypographyH2,\n} from \"@brightlocal/ui-components\";\nimport {\n  Building,\n  Globe,\n  Grid3x3,\n  House,\n  LayoutDashboard,\n  Link as LinkIcon,\n  Menu,\n  Sparkles,\n  Star,\n  Store,\n  TrendingUp,\n} from \"@brightlocal/icons\";\n\n// Sidebar nav icons: 20px (size-5), default stroke — the project's\n// curated convention (rules/05-product-map.md).\nconst TOP_ITEMS = [\n  { id: \"your-locations\", label: \"Your Locations\", icon: House },\n];\n\nconst LOCATION_ITEMS = [\n  { id: \"location-summary\", label: \"Location Summary\", icon: LayoutDashboard },\n  { id: \"ai-insights\", label: \"AI Insights\", icon: Sparkles },\n  { id: \"rankings\", label: \"Rankings\", icon: TrendingUp },\n  { id: \"local-search-grid\", label: \"Local Search Grid\", icon: Grid3x3 },\n  { id: \"citations\", label: \"Citations\", icon: LinkIcon, active: true },\n  { id: \"gbp\", label: \"GBP\", icon: Store },\n  { id: \"reputation-reviews\", label: \"Reputation & Reviews\", icon: Star },\n];\n\nconst TOOL_ITEMS = [\n  { id: \"location-manager\", label: \"Location Manager\", icon: Building },\n  { id: \"white-label\", label: \"White-label\", icon: Globe },\n];\n\nconst DIRECTORIES = [\n  { id: \"google\", name: \"Google Business Profile\", status: \"Live\", nap: \"Accurate\" },\n  { id: \"bing\", name: \"Bing Places\", status: \"Live\", nap: \"Accurate\" },\n  { id: \"apple\", name: \"Apple Maps\", status: \"Sync issue\", nap: \"Phone mismatch\" },\n  { id: \"yelp\", name: \"Yelp\", status: \"Live\", nap: \"Accurate\" },\n  { id: \"facebook\", name: \"Facebook\", status: \"Pending\", nap: \"—\" },\n];\n\nfunction NavGroup({ items }) {\n  return (\n    <SidebarGroup>\n      <SidebarGroupContent>\n        <SidebarMenu>\n          {items.map((item) => (\n            <SidebarMenuItem key={item.id}>\n              <SidebarMenuButton\n                dataHook={`nav-${item.id}`}\n                isActive={item.active}\n              >\n                {item.icon ? <item.icon className=\"size-5\" /> : null}\n                <span>{item.label}</span>\n              </SidebarMenuButton>\n            </SidebarMenuItem>\n          ))}\n        </SidebarMenu>\n      </SidebarGroupContent>\n    </SidebarGroup>\n  );\n}\n\nexport default function CitationsHub() {\n  return (\n    <SidebarProvider dataHook=\"citations-hub-sidebar-provider\" defaultOpen>\n      <GlobalLayout dataHook=\"global-layout\">\n        <GlobalLayoutSidebar dataHook=\"global-layout-sidebar\">\n          <Sidebar dataHook=\"app-sidebar\">\n            <SidebarHeader>\n              <Logo className=\"h-6\" dataHook=\"sidebar-logo\" />\n            </SidebarHeader>\n            <SidebarContent dataHook=\"sidebar-content\">\n              <NavGroup items={TOP_ITEMS} />\n              <Separator spacing=\"md\" dataHook=\"sidebar-separator-1\" />\n              <NavGroup items={LOCATION_ITEMS} />\n              <Separator spacing=\"md\" dataHook=\"sidebar-separator-2\" />\n              <NavGroup items={TOOL_ITEMS} />\n            </SidebarContent>\n            <SidebarFooter dataHook=\"sidebar-footer\">\n              <SidebarMenu>\n                <SidebarMenuItem>\n                  <SidebarAccountDropdown\n                    dataHook=\"sidebar-account-dropdown\"\n                    name=\"Andy Smith\"\n                    email=\"andy@acmecorp.com\"\n                    avatar={\n                      <Avatar dataHook=\"sidebar-user-avatar\">\n                        <AvatarFallback>AS</AvatarFallback>\n                      </Avatar>\n                    }\n                    menuGroups={[\n                      [\n                        { label: \"Account settings\" },\n                        { label: \"Notification preferences\" },\n                      ],\n                      [{ label: \"Log out\" }],\n                    ]}\n                    side=\"top\"\n                    align=\"end\"\n                  />\n                </SidebarMenuItem>\n              </SidebarMenu>\n            </SidebarFooter>\n          </Sidebar>\n        </GlobalLayoutSidebar>\n\n        <GlobalLayoutContent dataHook=\"global-layout-content\">\n          {/* Mobile top bar — hamburger (≡, matching live) + logo below\n              lg; 44px touch target, 20px glyph, no border (matching\n              live). SidebarTrigger opens the DS's built-in mobile\n              sheet. */}\n          <header className=\"flex items-center gap-1 px-1 py-1 lg:hidden\">\n            <SidebarTrigger dataHook=\"mobile-sidebar-trigger\" className=\"size-11\">\n              <Menu className=\"size-5\" />\n            </SidebarTrigger>\n            <Logo className=\"h-6\" dataHook=\"mobile-logo\" />\n          </header>\n          <GlobalLayoutContentHeader dataHook=\"page-header\">\n            <div className=\"flex min-w-0 items-center gap-3\">\n              <Avatar dataHook=\"location-avatar\">\n                <AvatarFallback>BF</AvatarFallback>\n              </Avatar>\n              <div className=\"min-w-0\">\n                <TypographyH2 dataHook=\"page-title\">Citations</TypographyH2>\n                <div className=\"text-muted-foreground flex flex-wrap items-center gap-2 text-sm\">\n                  <span>Blackberry Farm Park · Lewes, BN8 6JD</span>\n                  <Badge dataHook=\"location-status\">Active</Badge>\n                </div>\n              </div>\n            </div>\n            <Button dataHook=\"build-citations-button\">Build Citations</Button>\n          </GlobalLayoutContentHeader>\n\n          <GlobalLayoutContentBody dataHook=\"page-body\">\n            <div className=\"flex flex-col gap-6\">\n              {/* Score summary row */}\n              <div className=\"grid gap-4 sm:grid-cols-3\">\n                <Card variant=\"filled\" dataHook=\"stat-citations-found\">\n                  <CardContent>\n                    <p className=\"text-muted-foreground text-sm\">\n                      Citations found\n                    </p>\n                    <p className=\"text-2xl font-bold\">53 / 60</p>\n                    <p className=\"text-muted-foreground text-xs\">\n                      7 opportunities available\n                    </p>\n                  </CardContent>\n                </Card>\n                <Card variant=\"filled\" dataHook=\"stat-nap-accuracy\">\n                  <CardContent>\n                    <p className=\"text-muted-foreground text-sm\">\n                      NAP accuracy\n                    </p>\n                    <p className=\"text-2xl font-bold\">92%</p>\n                    <p className=\"text-muted-foreground text-xs\">\n                      1 listing needs attention\n                    </p>\n                  </CardContent>\n                </Card>\n                <Card variant=\"filled\" dataHook=\"stat-sync-status\">\n                  <CardContent>\n                    <p className=\"text-muted-foreground text-sm\">\n                      Listings sync\n                    </p>\n                    <p className=\"text-2xl font-bold\">4 / 5</p>\n                    <p className=\"text-muted-foreground text-xs\">\n                      Last synced 13 Jul 2026\n                    </p>\n                  </CardContent>\n                </Card>\n              </div>\n\n              {/* Directory table */}\n              <div>\n                <TypographyH2 dataHook=\"directories-title\">\n                  Directories\n                </TypographyH2>\n                <p className=\"text-muted-foreground text-sm\">\n                  Where your business listing appears and how accurate it is.\n                </p>\n              </div>\n              <Card variant=\"filled\" dataHook=\"directories-card\">\n                <CardContent>\n                  <Table dataHook=\"directories-table\">\n                    <TableHeader>\n                      <TableRow>\n                        <TableHead>Directory</TableHead>\n                        <TableHead>Status</TableHead>\n                        <TableHead>NAP accuracy</TableHead>\n                      </TableRow>\n                    </TableHeader>\n                    <TableBody>\n                      {DIRECTORIES.map((d) => (\n                        <TableRow key={d.id} dataHook={`directory-${d.id}-row`}>\n                          <TableCell>{d.name}</TableCell>\n                          <TableCell>\n                            <Badge dataHook={`directory-${d.id}-status`}>\n                              {d.status}\n                            </Badge>\n                          </TableCell>\n                          <TableCell>{d.nap}</TableCell>\n                        </TableRow>\n                      ))}\n                    </TableBody>\n                  </Table>\n                </CardContent>\n              </Card>\n            </div>\n          </GlobalLayoutContentBody>\n        </GlobalLayoutContent>\n      </GlobalLayout>\n    </SidebarProvider>\n  );\n}"
  },
  {
    "id": "location-dashboard",
    "label": "Location Dashboard",
    "description": "Full location overview: identity card, score, customer actions, rankings tabs.",
    "source": "// Location Dashboard — Full location overview: identity card, score, customer actions, rankings tabs.\n//\n// Hand-authored scaffold reconstructed from BrightLocal's Lab\n// \"Location Dashboard\" composition (storybook lab-location-dashboard —\n// its story source is minified upstream, so this is the editable\n// recreation; see BYODS-BRIGHTLOCAL-PLAN.md client findings).\n// Everything below is verified-rendering BL vocabulary. Edit freely —\n// this file is the authoring home; re-run\n// `node scripts/generate-registry-templates.mjs` after changes.\n\nimport {\n  Avatar,\n  AvatarFallback,\n  Badge,\n  Breadcrumb,\n  BreadcrumbItem,\n  BreadcrumbLink,\n  BreadcrumbList,\n  BreadcrumbPage,\n  BreadcrumbSeparator,\n  Button,\n  Card,\n  CardAction,\n  CardContent,\n  CardDescription,\n  CardFooter,\n  CardHeader,\n  CardTitle,\n  GlobalLayout,\n  GlobalLayoutContent,\n  GlobalLayoutContentBody,\n  GlobalLayoutContentHeader,\n  GlobalLayoutSidebar,\n  Logo,\n  Separator,\n  Sidebar,\n  SidebarAccountDropdown,\n  SidebarContent,\n  SidebarFooter,\n  SidebarGroup,\n  SidebarGroupContent,\n  SidebarHeader,\n  SidebarMenu,\n  SidebarMenuButton,\n  SidebarMenuItem,\n  SidebarProvider,\n  SidebarTrigger,\n  Tabs,\n  TabsContent,\n  TabsList,\n  TabsTrigger,\n} from \"@brightlocal/ui-components\";\nimport {\n  Building,\n  Globe,\n  Grid3x3,\n  House,\n  LayoutDashboard,\n  Link as LinkIcon,\n  Menu,\n  Sparkles,\n  Star,\n  Store,\n  TrendingUp,\n} from \"@brightlocal/icons\";\n\nconst TOP_ITEMS = [\n  { id: \"your-locations\", label: \"Your Locations\", icon: House },\n];\n\nconst LOCATION_ITEMS = [\n  {\n    id: \"location-summary\",\n    label: \"Location Summary\",\n    icon: LayoutDashboard,\n    active: true,\n  },\n  { id: \"ai-insights\", label: \"AI Insights\", icon: Sparkles },\n  { id: \"rankings\", label: \"Rankings\", icon: TrendingUp },\n  { id: \"local-search-grid\", label: \"Local Search Grid\", icon: Grid3x3 },\n  { id: \"citations\", label: \"Citations\", icon: LinkIcon },\n  { id: \"gbp\", label: \"GBP\", icon: Store },\n  { id: \"reputation-reviews\", label: \"Reputation & Reviews\", icon: Star },\n];\n\nconst TOOL_ITEMS = [\n  { id: \"location-manager\", label: \"Location Manager\", icon: Building },\n  { id: \"white-label\", label: \"White-label\", icon: Globe },\n];\n\nfunction NavGroup({ items }) {\n  return (\n    <SidebarGroup>\n      <SidebarGroupContent>\n        <SidebarMenu>\n          {items.map((item) => (\n            <SidebarMenuItem key={item.id}>\n              <SidebarMenuButton\n                dataHook={`nav-${item.id}`}\n                isActive={item.active}\n              >\n                {item.icon ? <item.icon className=\"size-5\" /> : null}\n                <span>{item.label}</span>\n              </SidebarMenuButton>\n            </SidebarMenuItem>\n          ))}\n        </SidebarMenu>\n      </SidebarGroupContent>\n    </SidebarGroup>\n  );\n}\n\nexport default function LocationDashboard() {\n  return (\n    <SidebarProvider dataHook=\"location-dashboard-sidebar-provider\" defaultOpen>\n      <GlobalLayout dataHook=\"global-layout\">\n        <GlobalLayoutSidebar dataHook=\"global-layout-sidebar\">\n          <Sidebar dataHook=\"app-sidebar\">\n            <SidebarHeader>\n              <Logo className=\"h-6\" dataHook=\"sidebar-logo\" />\n            </SidebarHeader>\n            <SidebarContent dataHook=\"sidebar-content\">\n              <NavGroup items={TOP_ITEMS} />\n              <Separator spacing=\"md\" dataHook=\"sidebar-separator-1\" />\n              <NavGroup items={LOCATION_ITEMS} />\n              <Separator spacing=\"md\" dataHook=\"sidebar-separator-2\" />\n              <NavGroup items={TOOL_ITEMS} />\n            </SidebarContent>\n            <SidebarFooter dataHook=\"sidebar-footer\">\n              <SidebarMenu>\n                <SidebarMenuItem>\n                  <SidebarAccountDropdown\n                    dataHook=\"sidebar-account-dropdown\"\n                    name=\"Andy Smith\"\n                    email=\"andy@acmecorp.com\"\n                    avatar={\n                      <Avatar dataHook=\"sidebar-user-avatar\">\n                        <AvatarFallback>AS</AvatarFallback>\n                      </Avatar>\n                    }\n                    menuGroups={[\n                      [\n                        { label: \"Account settings\" },\n                        { label: \"Notification preferences\" },\n                      ],\n                      [{ label: \"Log out\" }],\n                    ]}\n                    side=\"top\"\n                    align=\"end\"\n                  />\n                </SidebarMenuItem>\n              </SidebarMenu>\n            </SidebarFooter>\n          </Sidebar>\n        </GlobalLayoutSidebar>\n\n        <GlobalLayoutContent dataHook=\"global-layout-content\">\n          {/* Mobile top bar — see rules/05-product-map.md. */}\n          <header className=\"flex items-center gap-1 px-1 py-1 lg:hidden\">\n            <SidebarTrigger dataHook=\"mobile-sidebar-trigger\" className=\"size-11\">\n              <Menu className=\"size-5\" />\n            </SidebarTrigger>\n            <Logo className=\"h-6\" dataHook=\"mobile-logo\" />\n          </header>\n\n          {/* Page header — breadcrumb + date scope (this page keeps its\n              identity in the body card, so the header stays the\n              breadcrumb bar like the live dashboard). */}\n          <GlobalLayoutContentHeader dataHook=\"page-header\">\n            <Breadcrumb dataHook=\"location-breadcrumb\">\n              <BreadcrumbList>\n                <BreadcrumbItem>\n                  <BreadcrumbLink href=\"#\">All locations</BreadcrumbLink>\n                </BreadcrumbItem>\n                <BreadcrumbSeparator />\n                <BreadcrumbItem>\n                  <BreadcrumbPage>Bailiffscourt Hotel &amp; Spa</BreadcrumbPage>\n                </BreadcrumbItem>\n              </BreadcrumbList>\n            </Breadcrumb>\n            <Button variant=\"outline\" dataHook=\"date-scope-button\">\n              April 23rd, 2026\n            </Button>\n          </GlobalLayoutContentHeader>\n\n          <GlobalLayoutContentBody dataHook=\"page-body\">\n            <div className=\"grid gap-6 lg:grid-cols-3\">\n        {/* Identity card */}\n        <Card variant=\"filled\" dataHook=\"location-card\">\n          <CardHeader dataHook=\"location-card-header\">\n            <CardTitle>Bailiffscourt Hotel &amp; Spa</CardTitle>\n            <CardDescription>★ 4.4 (764 reviews)</CardDescription>\n            <CardAction>\n              <Badge dataHook=\"location-status\">Active</Badge>\n            </CardAction>\n          </CardHeader>\n          <CardContent>\n            <div className=\"grid gap-1 text-sm text-muted-foreground\">\n              <span>Littlehampton, BN17 5RW</span>\n              <span>Hotel</span>\n              <span>+44 1903 723511</span>\n            </div>\n          </CardContent>\n          <CardFooter>\n            <Button variant=\"outline\" dataHook=\"edit-location-button\">\n              Edit location\n            </Button>\n          </CardFooter>\n        </Card>\n\n        {/* Location score */}\n        <Card variant=\"filled\" dataHook=\"location-score-card\">\n          <CardHeader>\n            <CardTitle>Location Score</CardTitle>\n          </CardHeader>\n          <CardContent>\n            <div className=\"flex flex-col items-center gap-2 py-2\">\n              <span className=\"text-6xl font-semibold\" data-hook=\"location-score-value\">\n                58\n              </span>\n              <Badge dataHook=\"location-score-delta\">+3 since April 16</Badge>\n              <p className=\"pt-2 text-center text-sm text-muted-foreground\">\n                You&rsquo;re ranking #1 locally for &ldquo;hotel spa\n                retreat&rdquo; and outperforming 6 of your 10 nearest\n                competitors on website authority.\n              </p>\n            </div>\n          </CardContent>\n        </Card>\n\n        {/* Customer actions — nested condensed stat tiles */}\n        <Card variant=\"filled\" dataHook=\"customer-actions-card\">\n          <CardHeader dataHook=\"customer-actions-header\">\n            <CardTitle>Customer actions</CardTitle>\n            <CardDescription>This month vs last month</CardDescription>\n          </CardHeader>\n          <CardContent>\n            <div className=\"grid gap-3\">\n              <Card density=\"condensed\" variant=\"filled\" dataHook=\"call-clicks-tile\">\n                <CardContent>\n                  <p className=\"text-sm text-muted-foreground\">Call clicks</p>\n                  <div className=\"flex items-baseline justify-between\">\n                    <span className=\"text-2xl font-semibold\">312</span>\n                    <Badge dataHook=\"call-clicks-delta\">↑ 8%</Badge>\n                  </div>\n                </CardContent>\n              </Card>\n              <Card density=\"condensed\" variant=\"filled\" dataHook=\"website-clicks-tile\">\n                <CardContent>\n                  <p className=\"text-sm text-muted-foreground\">Website clicks</p>\n                  <div className=\"flex items-baseline justify-between\">\n                    <span className=\"text-2xl font-semibold\">1,847</span>\n                    <Badge dataHook=\"website-clicks-delta\">↑ 14%</Badge>\n                  </div>\n                </CardContent>\n              </Card>\n              <Card density=\"condensed\" variant=\"filled\" dataHook=\"direction-requests-tile\">\n                <CardContent>\n                  <p className=\"text-sm text-muted-foreground\">Direction requests</p>\n                  <div className=\"flex items-baseline justify-between\">\n                    <span className=\"text-2xl font-semibold\">428</span>\n                    <Badge variant=\"destructive\" dataHook=\"direction-requests-delta\">\n                      ↓ 3%\n                    </Badge>\n                  </div>\n                </CardContent>\n              </Card>\n            </div>\n          </CardContent>\n        </Card>\n\n        {/* Rankings — full-width tabs section */}\n        <Card variant=\"filled\" className=\"lg:col-span-3\" dataHook=\"visibility-card\">\n          <CardHeader dataHook=\"visibility-header\">\n            <CardTitle>Visibility</CardTitle>\n            <CardDescription>\n              Rank tracking across Google Search, Maps, and citations.\n            </CardDescription>\n            <CardAction>\n              <Button dataHook=\"run-audit-button\">Run new audit</Button>\n            </CardAction>\n          </CardHeader>\n          <CardContent>\n            <Tabs defaultValue=\"rankings\" dataHook=\"visibility-tabs\">\n              <TabsList>\n                <TabsTrigger value=\"rankings\" dataHook=\"tab-rankings\">\n                  Rank Tracking\n                </TabsTrigger>\n                <TabsTrigger value=\"citations\" dataHook=\"tab-citations\">\n                  Citation Health\n                </TabsTrigger>\n              </TabsList>\n              <TabsContent value=\"rankings\">\n                <div className=\"grid gap-3 py-4 sm:grid-cols-3\">\n                  <Card density=\"condensed\" variant=\"filled\" dataHook=\"avg-position-tile\">\n                    <CardContent>\n                      <p className=\"text-sm text-muted-foreground\">Avg. ranking position</p>\n                      <div className=\"flex items-baseline justify-between\">\n                        <span className=\"text-2xl font-semibold\">2.2</span>\n                        <Badge dataHook=\"avg-position-delta\">↑ 0.9 better</Badge>\n                      </div>\n                    </CardContent>\n                  </Card>\n                  <Card density=\"condensed\" variant=\"filled\" dataHook=\"top3-tile\">\n                    <CardContent>\n                      <p className=\"text-sm text-muted-foreground\">Keywords in top 3</p>\n                      <div className=\"flex items-baseline justify-between\">\n                        <span className=\"text-2xl font-semibold\">28</span>\n                        <Badge dataHook=\"top3-delta\">↑ 4 keywords</Badge>\n                      </div>\n                    </CardContent>\n                  </Card>\n                  <Card density=\"condensed\" variant=\"filled\" dataHook=\"citations-tile\">\n                    <CardContent>\n                      <p className=\"text-sm text-muted-foreground\">Citations found</p>\n                      <div className=\"flex items-baseline justify-between\">\n                        <span className=\"text-2xl font-semibold\">53 / 60</span>\n                        <Badge variant=\"outline\" dataHook=\"citations-status\">\n                          Action needed\n                        </Badge>\n                      </div>\n                    </CardContent>\n                  </Card>\n                </div>\n              </TabsContent>\n              <TabsContent value=\"citations\">\n                <p className=\"py-6 text-sm text-muted-foreground\">\n                  Citation health details — replace with a DataTable of\n                  directories once the blocks source lands.\n                </p>\n              </TabsContent>\n            </Tabs>\n          </CardContent>\n        </Card>\n            </div>\n          </GlobalLayoutContentBody>\n        </GlobalLayoutContent>\n      </GlobalLayout>\n    </SidebarProvider>\n  );\n}"
  },
  {
    "id": "location-summary",
    "label": "Location Summary",
    "description": "The near-product location summary: app shell + canonical photo header + welcome/insights card, Location Score, foundation cards.",
    "source": "// Location Summary — The near-product location summary: app shell + canonical photo header + welcome/insights card, Location Score, foundation cards.\n//\n// Composed from the verified building blocks: page-skeleton's app shell\n// (sidebar + mobile bar + Andy Smith persona), the location-page-header\n// recipe (hand-authored from the LIVE platform DOM), and the summary\n// body from the live \"Welcome back\" page (14 Jul screenshot): welcome\n// card + insights CTA, Location Score with Foundation/Visibility\n// sub-scores, and the Build-your-foundation cards with per-metric\n// progress rows. Edit freely; re-run\n// `node scripts/generate-registry-templates.mjs`.\n\nimport {\n  AspectRatio,\n  Avatar,\n  AvatarFallback,\n  Badge,\n  Button,\n  Card,\n  CardContent,\n  GlobalLayout,\n  GlobalLayoutContent,\n  GlobalLayoutContentBody,\n  GlobalLayoutContentHeader,\n  GlobalLayoutSidebar,\n  Logo,\n  Progress,\n  Separator,\n  Sidebar,\n  SidebarAccountDropdown,\n  SidebarContent,\n  SidebarFooter,\n  SidebarGroup,\n  SidebarGroupContent,\n  SidebarHeader,\n  SidebarMenu,\n  SidebarMenuButton,\n  SidebarMenuItem,\n  SidebarProvider,\n  SidebarTrigger,\n  TypographyH2,\n  TypographySmall,\n} from \"@brightlocal/ui-components\";\nimport {\n  Building,\n  Globe,\n  Grid3x3,\n  House,\n  LayoutDashboard,\n  Link as LinkIcon,\n  MapPin,\n  Menu,\n  Sparkles,\n  Star,\n  Store,\n  TrendingUp,\n} from \"@brightlocal/icons\";\n\nconst TOP_ITEMS = [\n  { id: \"your-locations\", label: \"Your Locations\", icon: House },\n];\n\nconst LOCATION_ITEMS = [\n  {\n    id: \"location-summary\",\n    label: \"Location Summary\",\n    icon: LayoutDashboard,\n    active: true,\n  },\n  { id: \"ai-insights\", label: \"AI Insights\", icon: Sparkles },\n  { id: \"rankings\", label: \"Rankings\", icon: TrendingUp },\n  { id: \"local-search-grid\", label: \"Local Search Grid\", icon: Grid3x3 },\n  { id: \"citations\", label: \"Citations\", icon: LinkIcon },\n  { id: \"gbp\", label: \"GBP\", icon: Store },\n  { id: \"reputation-reviews\", label: \"Reputation & Reviews\", icon: Star },\n];\n\nconst TOOL_ITEMS = [\n  { id: \"location-manager\", label: \"Location Manager\", icon: Building },\n  { id: \"white-label\", label: \"White-label\", icon: Globe },\n];\n\nconst WEBSITE_METRICS = [\n  { id: \"conversion-ux\", label: \"Conversion UX\", score: 15 },\n  { id: \"keyword-coverage\", label: \"Keyword coverage\", score: 100 },\n  { id: \"page-optimization\", label: \"Page optimization\", score: 100 },\n  { id: \"technical-health\", label: \"Technical health\", score: 60 },\n  { id: \"local-intent\", label: \"Local intent & linking\", score: 14 },\n];\n\nconst GBP_METRICS = [\n  { id: \"activity\", label: \"Activity & freshness\", score: 100 },\n  { id: \"conversion-tracking\", label: \"Conversion tracking\", score: 50 },\n  { id: \"profile-completeness\", label: \"Profile completeness\", score: 60 },\n  { id: \"nap-alignment\", label: \"NAP alignment\", score: 30 },\n  { id: \"category-accuracy\", label: \"Category & service accuracy\", score: 30 },\n];\n\nfunction NavGroup({ items }) {\n  return (\n    <SidebarGroup>\n      <SidebarGroupContent>\n        <SidebarMenu>\n          {items.map((item) => (\n            <SidebarMenuItem key={item.id}>\n              <SidebarMenuButton\n                dataHook={`nav-${item.id}`}\n                isActive={item.active}\n              >\n                {item.icon ? <item.icon className=\"size-5\" /> : null}\n                <span>{item.label}</span>\n              </SidebarMenuButton>\n            </SidebarMenuItem>\n          ))}\n        </SidebarMenu>\n      </SidebarGroupContent>\n    </SidebarGroup>\n  );\n}\n\nfunction MetricRow({ id, label, score }) {\n  return (\n    <div className=\"flex items-center gap-3\" data-hook={`metric-${id}-row`}>\n      <span className=\"w-40 shrink-0 text-sm\">{label}</span>\n      <Progress value={score} className=\"h-2 flex-1\" dataHook={`metric-${id}-progress`} />\n      <span className=\"text-muted-foreground w-16 shrink-0 text-right text-sm tabular-nums\">\n        {score}/100\n      </span>\n    </div>\n  );\n}\n\nexport default function LocationSummary() {\n  return (\n    <SidebarProvider dataHook=\"location-summary-sidebar-provider\" defaultOpen>\n      <GlobalLayout dataHook=\"global-layout\">\n        <GlobalLayoutSidebar dataHook=\"global-layout-sidebar\">\n          <Sidebar dataHook=\"app-sidebar\">\n            <SidebarHeader>\n              <Logo className=\"h-6\" dataHook=\"sidebar-logo\" />\n            </SidebarHeader>\n            <SidebarContent dataHook=\"sidebar-content\">\n              <NavGroup items={TOP_ITEMS} />\n              <Separator spacing=\"md\" dataHook=\"sidebar-separator-1\" />\n              <NavGroup items={LOCATION_ITEMS} />\n              <Separator spacing=\"md\" dataHook=\"sidebar-separator-2\" />\n              <NavGroup items={TOOL_ITEMS} />\n            </SidebarContent>\n            <SidebarFooter dataHook=\"sidebar-footer\">\n              <SidebarMenu>\n                <SidebarMenuItem>\n                  <SidebarAccountDropdown\n                    dataHook=\"sidebar-account-dropdown\"\n                    name=\"Andy Smith\"\n                    email=\"andy@acmecorp.com\"\n                    avatar={\n                      <Avatar dataHook=\"sidebar-user-avatar\">\n                        <AvatarFallback>AS</AvatarFallback>\n                      </Avatar>\n                    }\n                    menuGroups={[\n                      [\n                        { label: \"Account settings\" },\n                        { label: \"Notification preferences\" },\n                      ],\n                      [{ label: \"Log out\" }],\n                    ]}\n                    side=\"top\"\n                    align=\"end\"\n                  />\n                </SidebarMenuItem>\n              </SidebarMenu>\n            </SidebarFooter>\n          </Sidebar>\n        </GlobalLayoutSidebar>\n\n        <GlobalLayoutContent dataHook=\"global-layout-content\">\n          {/* Mobile top bar — see rules/05-product-map.md. */}\n          <header className=\"flex items-center gap-1 px-1 py-1 lg:hidden\">\n            <SidebarTrigger dataHook=\"mobile-sidebar-trigger\" className=\"size-11\">\n              <Menu className=\"size-5\" />\n            </SidebarTrigger>\n            <Logo className=\"h-6\" dataHook=\"mobile-logo\" />\n          </header>\n\n          {/* Canonical page header — the location-page-header recipe. */}\n          <GlobalLayoutContentHeader dataHook=\"page-header\">\n            <div className=\"flex w-full flex-col gap-2 md:flex-row md:items-center md:justify-between\">\n              <div\n                className=\"flex w-full flex-col gap-4 md:flex-row md:items-center\"\n                data-hook=\"location-header-card\"\n              >\n                <div className=\"w-full md:hidden\">\n                  <AspectRatio dataHook=\"location-header-card-photo-sm\" ratio={21 / 9}>\n                    <img\n                      alt=\"Brighton Bierhaus location photo\"\n                      className=\"h-full w-full rounded-xl object-cover\"\n                      src=\"https://images.unsplash.com/photo-1514933651103-005eec06c04b?w=800&q=80\"\n                    />\n                  </AspectRatio>\n                </div>\n                <div className=\"hidden w-24 shrink-0 md:block\">\n                  <AspectRatio dataHook=\"location-header-card-photo-lg\" ratio={16 / 10}>\n                    <img\n                      alt=\"Brighton Bierhaus location photo\"\n                      className=\"h-full w-full rounded-xl object-cover\"\n                      src=\"https://images.unsplash.com/photo-1514933651103-005eec06c04b?w=400&q=80\"\n                    />\n                  </AspectRatio>\n                </div>\n                <div className=\"flex flex-col gap-1.5\">\n                  <TypographyH2 dataHook=\"location-business-name\">\n                    Brighton Bierhaus\n                  </TypographyH2>\n                  <div className=\"flex flex-wrap items-center gap-x-3 gap-y-1 text-sm text-muted-foreground\">\n                    <span className=\"flex items-center gap-1.5\">\n                      <MapPin className=\"size-3.5 shrink-0\" />\n                      <span>Brighton and Hove, BN2 0JB</span>\n                    </span>\n                    <span className=\"flex items-center gap-1.5\">\n                      <Star className=\"size-3.5 fill-yellow-400 stroke-yellow-400\" />\n                      <span>4.6 (539 reviews)</span>\n                    </span>\n                    <span className=\"basis-full md:basis-auto\">\n                      {/* Status badge — success tokens via className: the DS\n                          ships no success variant (rules/90-audit.md). */}\n                      <Badge\n                        dataHook=\"location-status-badge-active\"\n                        className=\"border-transparent bg-success-background text-success-foreground\"\n                      >\n                        Active\n                      </Badge>\n                    </span>\n                  </div>\n                </div>\n              </div>\n              <div className=\"md:shrink-0\">\n                <TypographySmall dataHook=\"location-last-updated\">\n                  Last updated: 14/07/26\n                </TypographySmall>\n              </div>\n            </div>\n          </GlobalLayoutContentHeader>\n\n          <GlobalLayoutContentBody dataHook=\"page-body\">\n            <div className=\"flex flex-col gap-6\">\n              {/* Welcome + Location Score — the welcome-insights-card\n                  recipe (full width, donut ring, Sparkles CTA). Copied,\n                  not included: screens are self-contained JSX — the\n                  recipe file is the authoring source; re-sync on change. */}\n              <Card variant=\"filled\" className=\"w-full\" dataHook=\"welcome-card\">\n                <CardContent>\n                  <div className=\"grid items-center gap-8 lg:grid-cols-[1fr_auto]\">\n                    <div className=\"flex flex-col gap-3\">\n                      <TypographyH2 dataHook=\"welcome-title\">\n                        Welcome back, Andy Smith\n                      </TypographyH2>\n                      <p className=\"text-muted-foreground max-w-prose text-sm\">\n                        Brighton Bierhaus has a strong Google presence with an\n                        excellent rating and plenty of photos. The fastest\n                        gains now are to fix website blockers, strengthen\n                        local signals on your site, expand your GBP to capture\n                        takeaway searches, and close citation gaps to lift\n                        visibility across Brighton.\n                      </p>\n                      <div className=\"text-muted-foreground flex items-center gap-4 text-sm\">\n                        <span>5 insights</span>\n                        <span>28 recommendations</span>\n                      </div>\n                      <div>\n                        <Button dataHook=\"see-all-insights-button\">\n                          See all insights\n                          <Sparkles />\n                        </Button>\n                      </div>\n                    </div>\n                    <div className=\"flex flex-col items-center gap-2\" data-hook=\"location-score\">\n                      <span className=\"text-muted-foreground text-sm\">\n                        Location Score\n                      </span>\n                      <div className=\"relative size-36\">\n                        <svg viewBox=\"0 0 120 120\" className=\"size-full -rotate-90\">\n                          <circle\n                            cx=\"60\"\n                            cy=\"60\"\n                            r=\"52\"\n                            fill=\"none\"\n                            strokeWidth=\"10\"\n                            className=\"stroke-muted\"\n                          />\n                          <circle\n                            cx=\"60\"\n                            cy=\"60\"\n                            r=\"52\"\n                            fill=\"none\"\n                            strokeWidth=\"10\"\n                            strokeLinecap=\"round\"\n                            strokeDasharray=\"326.7\"\n                            strokeDashoffset={326.7 * (1 - 32 / 100)}\n                            className=\"stroke-orange-400\"\n                          />\n                        </svg>\n                        <div className=\"absolute inset-0 flex flex-col items-center justify-center\">\n                          <span className=\"font-display text-4xl font-semibold\">\n                            32\n                          </span>\n                          <span className=\"text-muted-foreground text-xs\">\n                            /100\n                          </span>\n                        </div>\n                      </div>\n                      <div className=\"text-muted-foreground flex gap-4 text-xs\">\n                        <span>Foundation 64/100</span>\n                        <span>Visibility 0/100</span>\n                      </div>\n                    </div>\n                  </div>\n                </CardContent>\n              </Card>\n\n              {/* Build your foundation */}\n              <div>\n                <TypographyH2 dataHook=\"foundation-title\">\n                  Build your foundation\n                </TypographyH2>\n                <p className=\"text-muted-foreground text-sm\">\n                  Your foundations are what impact how easily you get found\n                  online.\n                </p>\n              </div>\n              <div className=\"grid gap-6 lg:grid-cols-2\">\n                {/* foundation-metric-card recipe ×2 (copied; recipe file\n                    is the authoring source). */}\n                <Card variant=\"filled\" dataHook=\"website-content-card\">\n                  <CardContent>\n                    <div className=\"flex flex-col gap-4\">\n                      <div className=\"flex items-center gap-2\">\n                        <Globe className=\"text-muted-foreground size-5\" />\n                        <span className=\"text-sm font-medium\">\n                          Website and content\n                        </span>\n                      </div>\n                      <div className=\"flex items-baseline gap-1\">\n                        <span className=\"text-3xl font-bold\">68</span>\n                        <span className=\"text-muted-foreground text-sm\">/100</span>\n                      </div>\n                      <div className=\"flex flex-col gap-3\">\n                        {WEBSITE_METRICS.map((m) => (\n                          <MetricRow key={m.id} {...m} />\n                        ))}\n                      </div>\n                    </div>\n                  </CardContent>\n                </Card>\n                <Card variant=\"filled\" dataHook=\"gbp-card\">\n                  <CardContent>\n                    <div className=\"flex flex-col gap-4\">\n                      <div className=\"flex items-center gap-2\">\n                        <Store className=\"text-muted-foreground size-5\" />\n                        <span className=\"text-sm font-medium\">\n                          Google Business Profile\n                        </span>\n                      </div>\n                      <div className=\"flex items-baseline gap-1\">\n                        <span className=\"text-3xl font-bold\">54</span>\n                        <span className=\"text-muted-foreground text-sm\">/100</span>\n                      </div>\n                      <div className=\"flex flex-col gap-3\">\n                        {GBP_METRICS.map((m) => (\n                          <MetricRow key={m.id} {...m} />\n                        ))}\n                      </div>\n                    </div>\n                  </CardContent>\n                </Card>\n              </div>\n            </div>\n          </GlobalLayoutContentBody>\n        </GlobalLayoutContent>\n      </GlobalLayout>\n    </SidebarProvider>\n  );\n}"
  },
  {
    "id": "page-skeleton",
    "label": "Page Skeleton",
    "description": "Sidebar shell + location page header + content region, DS compounds throughout.",
    "source": "// Page Skeleton — Sidebar shell + location page header + content region, DS compounds throughout.\n//\n// Composed the way BrightLocal's own blocks-sidebar--default story does:\n// SidebarProvider > GlobalLayout > GlobalLayoutSidebar > Sidebar(...) +\n// GlobalLayoutContent > ContentHeader / ContentBody. No hand-rolled nav —\n// the sidebar body is the shipped Sidebar compound family. Nav content\n// matches the live logged-in dashboard (July 2026: Blackberry Farm Park /\n// Location Summary). The content body is a placeholder region to build on.\n// Edit freely; re-run `node scripts/generate-registry-templates.mjs`.\n\nimport {\n  Avatar,\n  AvatarFallback,\n  Badge,\n  Card,\n  CardContent,\n  GlobalLayout,\n  GlobalLayoutContent,\n  GlobalLayoutContentBody,\n  GlobalLayoutContentHeader,\n  GlobalLayoutSidebar,\n  Logo,\n  Separator,\n  Sidebar,\n  SidebarAccountDropdown,\n  SidebarContent,\n  SidebarFooter,\n  SidebarGroup,\n  SidebarGroupContent,\n  SidebarHeader,\n  SidebarMenu,\n  SidebarMenuButton,\n  SidebarMenuItem,\n  SidebarProvider,\n  SidebarTrigger,\n  TypographyH2,\n} from \"@brightlocal/ui-components\";\nimport {\n  Building,\n  Globe,\n  Grid3x3,\n  House,\n  LayoutDashboard,\n  Link,\n  Menu,\n  Sparkles,\n  Star,\n  Store,\n  TrendingUp,\n} from \"@brightlocal/icons\";\n\n// Sidebar nav icons: 20px (size-5), default stroke — the project's\n// curated convention (rules/05-product-map.md). Deliberately NOT the\n// live platform's 24px/1.33, which contradicts their own docs.\nconst TOP_ITEMS = [\n  { id: \"your-locations\", label: \"Your Locations\", icon: House },\n];\n\nconst LOCATION_ITEMS = [\n  {\n    id: \"location-summary\",\n    label: \"Location Summary\",\n    icon: LayoutDashboard,\n    active: true,\n  },\n  { id: \"ai-insights\", label: \"AI Insights\", icon: Sparkles },\n  { id: \"rankings\", label: \"Rankings\", icon: TrendingUp },\n  { id: \"local-search-grid\", label: \"Local Search Grid\", icon: Grid3x3 },\n  { id: \"citations\", label: \"Citations\", icon: Link },\n  { id: \"gbp\", label: \"GBP\", icon: Store },\n  { id: \"reputation-reviews\", label: \"Reputation & Reviews\", icon: Star },\n];\n\nconst TOOL_ITEMS = [\n  { id: \"location-manager\", label: \"Location Manager\", icon: Building },\n  { id: \"white-label\", label: \"White-label\", icon: Globe },\n];\n\nfunction NavGroup({ items }) {\n  return (\n    <SidebarGroup>\n      <SidebarGroupContent>\n        <SidebarMenu>\n          {items.map((item) => (\n            <SidebarMenuItem key={item.id}>\n              <SidebarMenuButton\n                dataHook={`nav-${item.id}`}\n                isActive={item.active}\n              >\n                {item.icon ? <item.icon className=\"size-5\" /> : null}\n                <span>{item.label}</span>\n              </SidebarMenuButton>\n            </SidebarMenuItem>\n          ))}\n        </SidebarMenu>\n      </SidebarGroupContent>\n    </SidebarGroup>\n  );\n}\n\nexport default function PageSkeleton() {\n  return (\n    <SidebarProvider dataHook=\"page-skeleton-sidebar-provider\" defaultOpen>\n      <GlobalLayout dataHook=\"global-layout\">\n        <GlobalLayoutSidebar dataHook=\"global-layout-sidebar\">\n          <Sidebar dataHook=\"app-sidebar\">\n            <SidebarHeader>\n              <Logo className=\"h-6\" dataHook=\"sidebar-logo\" />\n            </SidebarHeader>\n            <SidebarContent dataHook=\"sidebar-content\">\n              <NavGroup items={TOP_ITEMS} />\n              <Separator spacing=\"md\" dataHook=\"sidebar-separator-1\" />\n              <NavGroup items={LOCATION_ITEMS} />\n              <Separator spacing=\"md\" dataHook=\"sidebar-separator-2\" />\n              <NavGroup items={TOOL_ITEMS} />\n            </SidebarContent>\n            <SidebarFooter dataHook=\"sidebar-footer\">\n              {/* Account menu — the shipped SidebarAccountDropdown\n                  (name/email trigger + divider-grouped menu), mounted\n                  exactly as the DS's own story does. */}\n              <SidebarMenu>\n                <SidebarMenuItem>\n                  <SidebarAccountDropdown\n                    dataHook=\"sidebar-account-dropdown\"\n                    name=\"Andy Smith\"\n                    email=\"andy@acmecorp.com\"\n                    avatar={\n                      <Avatar dataHook=\"sidebar-user-avatar\">\n                        <AvatarFallback>AS</AvatarFallback>\n                      </Avatar>\n                    }\n                    menuGroups={[\n                      [\n                        { label: \"Account settings\" },\n                        { label: \"Notification preferences\" },\n                      ],\n                      [{ label: \"Log out\" }],\n                    ]}\n                    side=\"top\"\n                    align=\"end\"\n                  />\n                </SidebarMenuItem>\n              </SidebarMenu>\n            </SidebarFooter>\n          </Sidebar>\n        </GlobalLayoutSidebar>\n\n        <GlobalLayoutContent dataHook=\"global-layout-content\">\n          {/* Mobile top bar — the live platform's responsive shell: the\n              sidebar is hidden below lg, and this bar (hamburger + logo)\n              takes over. SidebarTrigger opens the DS's built-in mobile\n              sheet — no hand-rolled drawer. Menu (≡) matches the live\n              platform's icon; size-11 = 44px minimum touch target with\n              the size-5 glyph matching the sidebar nav icons. No border\n              — the live platform's mobile bar has no dividing line. */}\n          <header className=\"flex items-center gap-1 px-1 py-1 lg:hidden\">\n            <SidebarTrigger dataHook=\"mobile-sidebar-trigger\" className=\"size-11\">\n              <Menu className=\"size-5\" />\n            </SidebarTrigger>\n            <Logo className=\"h-6\" dataHook=\"mobile-logo\" />\n          </header>\n          {/* Page header — location identity */}\n          <GlobalLayoutContentHeader dataHook=\"page-header\">\n            <div className=\"flex min-w-0 items-center gap-3\">\n              <Avatar dataHook=\"location-avatar\">\n                <AvatarFallback>BF</AvatarFallback>\n              </Avatar>\n              <div className=\"min-w-0\">\n                <TypographyH2 dataHook=\"page-title\">\n                  Blackberry Farm Park\n                </TypographyH2>\n                <div className=\"text-muted-foreground flex flex-wrap items-center gap-2 text-sm\">\n                  <span>Lewes, BN8 6JD</span>\n                  <span>★ 4.3 (878 reviews)</span>\n                  <Badge dataHook=\"location-status\">Active</Badge>\n                </div>\n              </div>\n            </div>\n            <span className=\"text-muted-foreground shrink-0 text-sm\">\n              Last updated: 12/07/26\n            </span>\n          </GlobalLayoutContentHeader>\n\n          {/* Page content — placeholder region to build on */}\n          <GlobalLayoutContentBody dataHook=\"page-body\">\n            <div className=\"flex flex-col gap-6\">\n              <Card variant=\"filled\" dataHook=\"content-primary-card\">\n                <CardContent>\n                  <p className=\"text-muted-foreground py-10 text-center text-sm\">\n                    Primary content — welcome card, score, insights.\n                  </p>\n                </CardContent>\n              </Card>\n              <div>\n                <TypographyH2 dataHook=\"section-title\">\n                  Section title\n                </TypographyH2>\n                <p className=\"text-muted-foreground text-sm\">\n                  One-line section description.\n                </p>\n              </div>\n              <div className=\"grid gap-6 sm:grid-cols-2\">\n                <Card variant=\"filled\" dataHook=\"section-card-1\">\n                  <CardContent>\n                    <p className=\"text-muted-foreground py-10 text-center text-sm\">\n                      Section card\n                    </p>\n                  </CardContent>\n                </Card>\n                <Card variant=\"filled\" dataHook=\"section-card-2\">\n                  <CardContent>\n                    <p className=\"text-muted-foreground py-10 text-center text-sm\">\n                      Section card\n                    </p>\n                  </CardContent>\n                </Card>\n              </div>\n            </div>\n          </GlobalLayoutContentBody>\n        </GlobalLayoutContent>\n      </GlobalLayout>\n    </SidebarProvider>\n  );\n}"
  }
] as const;
